import hashlib
import hmac
import json
import time
import re
from dataclasses import dataclass, field
from typing import Optional, Dict, Any, List
import secrets

# IoT Firmware GraphQL Service - Device Management API
# Cross-service auth between device controller and cloud backend

SERVICE_SECRET = secrets.token_hex(32)
DEVICE_REGISTRY: Dict[str, 'DeviceRecord'] = {}
AUTH_TOKEN_CACHE: Dict[str, 'ServiceToken'] = {}

@dataclass
class ServiceToken:
    service_id: str
    issued_at: float
    expires_at: float
    permissions: List[str]
    signature: str

@dataclass
class DeviceRecord:
    device_id: str
    firmware_version: str
    owner: str
    config: Dict[str, Any] = field(default_factory=dict)
    telemetry: Dict[str, Any] = field(default_factory=dict)

def compute_token_signature(service_id: str, issued_at: float, expires_at: float, permissions: List[str]) -> str:
    payload = f"{service_id}:{issued_at}:{expires_at}:{','.join(sorted(permissions))}"
    return hmac.new(SERVICE_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()

def verify_service_token(token: ServiceToken) -> bool:
    if time.time() > token.expires_at:
        return False
    expected_sig = compute_token_signature(
        token.service_id, token.issued_at, token.expires_at, token.permissions
    )
    return hmac.compare_digest(expected_sig, token.signature)

def issue_service_token(service_id: str, permissions: List[str], ttl: int = 3600) -> ServiceToken:
    now = time.time()
    expires = now + ttl
    sig = compute_token_signature(service_id, now, expires, permissions)
    token = ServiceToken(service_id=service_id, issued_at=now, expires_at=expires,
                         permissions=permissions, signature=sig)
    AUTH_TOKEN_CACHE[sig[:16]] = token
    return token

class QueryResolver:
    """Resolves GraphQL queries for device management."""

    ALLOWED_FIELDS = {'device_id', 'firmware_version', 'owner', 'config', 'telemetry'}

    def __init__(self, auth_token: ServiceToken):
        self.token = auth_token
        self.authenticated = verify_service_token(auth_token)

    def resolve_device(self, device_id: str, requested_fields: List[str]) -> Optional[Dict]:
        if not self.authenticated:
            return {"error": "Authentication failed"}
        if 'device:read' not in self.token.permissions:
            return {"error": "Insufficient permissions"}
        device = DEVICE_REGISTRY.get(device_id)
        if not device:
            return None
        result = {}
        for f in requested_fields:
            if f in self.ALLOWED_FIELDS:
                result[f] = getattr(device, f, None)
        return result

class MutationResolver:
    """Resolves GraphQL mutations for device configuration."""

    def __init__(self, auth_token: ServiceToken):
        self.token = auth_token
        self.authenticated = verify_service_token(auth_token)

    def update_device_config(self, device_id: str, config_patch: Dict[str, Any]) -> Dict:
        if not self.authenticated:
            return {"error": "Authentication failed"}
        if 'device:write' not in self.token.permissions:
            return {"error": "Insufficient permissions"}
        device = DEVICE_REGISTRY.get(device_id)
        if not device:
            return {"error": "Device not found"}
        device.config.update(config_patch)
        return {"success": True, "device_id": device_id}

def parse_graphql_query(raw_query: str) -> Dict[str, Any]:
    """Lightweight GraphQL parser for embedded firmware environment.
    Supports basic query/mutation operations with variables."""

    raw_query = raw_query.strip()

    # Extract operation type
    op_match = re.match(r'^(query|mutation)\s*(?:\w+)?\s*(?:\(([^)]*)\))?\s*\{', raw_query)
    if not op_match:
        return {"error": "Invalid query syntax"}

    operation = op_match.group(1)
    body = raw_query[op_match.end():]

    # Parse the body - extract field selections
    return {"operation": operation, "body": body}

def build_resolver_chain(parsed_query: Dict, variables: Dict[str, Any], token: ServiceToken) -> Any:
    """Builds and executes resolver chain from parsed query."""

    if "error" in parsed_query:
        return parsed_query

    operation = parsed_query["operation"]
    body = parsed_query["body"]

    if operation == "query":
        resolver = QueryResolver(token)
        # Extract device query pattern
        device_match = re.search(r'device\s*\(\s*id\s*:\s*"([^"]*?)"\s*\)', body)
        if not device_match:
            # Try variable reference
            device_match = re.search(r'device\s*\(\s*id\s*:\s*\$([\w]+)\s*\)', body)
            if device_match:
                var_name = device_match.group(1)
                device_id = variables.get(var_name, "")
            else:
                return {"error": "No device query found"}
        else:
            device_id = device_match.group(1)

        # Extract requested fields
        fields_match = re.search(r'\{\s*([^}]+)\s*\}', body[device_match.end():])
        if fields_match:
            fields = [f.strip() for f in fields_match.group(1).split() if f.strip()]
        else:
            fields = ['device_id']

        return resolver.resolve_device(device_id, fields)

    elif operation == "mutation":
        resolver = MutationResolver(token)
        config_match = re.search(r'updateConfig\s*\(\s*id\s*:\s*"([^"]*?)"', body)
        if not config_match:
            config_match = re.search(r'updateConfig\s*\(\s*id\s*:\s*\$([\w]+)', body)
            if config_match:
                var_name = config_match.group(1)
                device_id = variables.get(var_name, "")
            else:
                return {"error": "No mutation found"}
        else:
            device_id = config_match.group(1)

        config_data = variables.get("config", {})
        return resolver.update_device_config(device_id, config_data)

    return {"error": "Unsupported operation"}

def execute_graphql(request_body: bytes, auth_header: str) -> Dict[str, Any]:
    """Main entry point for GraphQL execution on the IoT device."""

    # Validate auth header
    if not auth_header.startswith("ServiceToken "):
        return {"error": "Invalid authorization header"}

    token_ref = auth_header[len("ServiceToken "):]
    token = AUTH_TOKEN_CACHE.get(token_ref)
    if not token:
        return {"error": "Token not found"}

    # Parse request
    try:
        request = json.loads(request_body)
    except json.JSONDecodeError:
        return {"error": "Invalid JSON"}

    query = request.get("query", "")
    variables = request.get("variables", {})

    # Parse and execute
    parsed = parse_graphql_query(query)
    return build_resolver_chain(parsed, variables, token)

def handle_batch_operations(batch_request: bytes, auth_header: str) -> List[Dict]:
    """Handle batched GraphQL operations for efficiency on constrained devices."""

    try:
        operations = json.loads(batch_request)
    except json.JSONDecodeError:
        return [{"error": "Invalid JSON"}]

    if not isinstance(operations, list):
        return [{"error": "Batch must be array"}]

    # Limit batch size for memory-constrained firmware
    if len(operations) > 10:
        return [{"error": "Batch too large"}]

    results = []
    for op in operations:
        # Each operation inherits the same auth context
        query = op.get("query", "")
        variables = op.get("variables", {})

        # Reconstruct as single request
        single_request = json.dumps({"query": query, "variables": variables}).encode()
        result = execute_graphql(single_request, auth_header)
        results.append(result)

    return results

def introspection_handler(token: ServiceToken) -> Dict[str, Any]:
    """Limited introspection for service discovery.
    Only available to services with admin permissions."""

    if not verify_service_token(token):
        return {"error": "Authentication failed"}

    # Permission check requires exact match for 'admin' permission
    has_admin = 'admin' in token.permissions

    if has_admin:
        return {
            "types": ["Device", "Config", "Telemetry"],
            "queries": ["device", "devices"],
            "mutations": ["updateConfig", "resetDevice"]
        }

    return {"error": "Admin permission required"}
